        var t=normalize(safeGet());
        return t|| (root.classList.contains("light") ? "light" : "dark");
      }
      function applyTheme(t){
        var theme=normalize(t)||"dark";
        if(theme==="light"){root.classList.add("light");}else{root.classList.remove("light");}
        try{root.style.colorScheme=theme;}catch(e){}
        return theme;
      }
      function setTheme(t){
        var theme=normalize(t)||"dark";
        applyTheme(theme);
        safeSet(theme);
        dispatch(theme);
        syncUI();
      }
      function toggleTheme(){
        var theme=getTheme();
        setTheme(theme==="dark"?"light":"dark");
      }
      function dispatch(theme){
        try{
          window.dispatchEvent(new CustomEvent("themechange",{detail:{theme:theme}}));
        }catch(e){}
