          icon.innerHTML='<path d="M12 18a6 6 0 1 0 0-12 6 6 0 0 0 0 12Zm0-16a1 1 0 0 1 1 1v1a1 1 0 1 1-2 0V3a1 1 0 0 1 1-1Zm0 18a1 1 0 0 1 1 1v1a1 1 0 1 1-2 0v-1a1 1 0 0 1 1-1ZM2 12a1 1 0 0 1 1-1h1a1 1 0 1 1 0 2H3a1 1 0 0 1-1-1Zm18 0a1 1 0 0 1 1-1h1a1 1 0 1 1 0 2h-1a1 1 0 0 1-1-1ZM4.22 4.22a1 1 0 0 1 1.41 0l.7.7a1 1 0 0 1-1.41 1.42l-.7-.7a1 1 0 0 1 0-1.42Zm13.45 13.45a1 1 0 0 1 1.41 0l.7.7a1 1 0 1 1-1.41 1.42l-.7-.7a1 1 0 0 1 0-1.42ZM19.78 4.22a1 1 0 0 1 0 1.42l-.7.7a1 1 0 0 1-1.41-1.42l.7-.7a1 1 0 0 1 1.41 0ZM6.33 17.67a1 1 0 0 1 0 1.42l-.7.7a1 1 0 1 1-1.41-1.42l.7-.7a1 1 0 0 1 1.41 0Z" fill="currentColor"></path>';
        }
      }
      function syncUI(){
        var theme=getTheme();
        var label=document.getElementById("themeLabel");
        var pill=document.getElementById("themePill");
        var value=document.getElementById("themeValue");
        var stored=normalize(safeGet());
        var storageValue=document.getElementById("storageValue");
        var storagePill=document.getElementById("storagePill");
        var statusOut=document.getElementById("statusOut");
        var statusPill=document.getElementById("statusPill");
        if(label) label.textContent = theme==="dark" ? "Sötét" : "Világos";
        if(pill) pill.textContent = theme==="dark" ? "DARK" : "LIGHT";
        if(value) value.textContent = theme;
        if(storageValue) storageValue.textContent = stored ? ("Tárolva: "+stored) : "Nincs tárolt érték";
        if(storagePill) storagePill.textContent = stored ? "Mentve" : "Üres";
        iconFor(theme);
        var now=new Date();
        var info={
          theme: theme,
          storedTheme: stored,
          documentClass: root.className,
          time: now.toISOString(),
          locale: navigator.language || null,
          timezone: (Intl && Intl.DateTimeFormat)? Intl.DateTimeFormat().resolvedOptions().timeZone : null
        };
        if(statusOut) statusOut.textContent = JSON.stringify(info,null,2);
        if(statusPill){
          var ok = theme==="dark" || theme==="light";
          statusPill.textContent = ok ? "OK" : "HIBA";
          statusPill.setAttribute("data-variant", ok ? "ok" : "warn");
        }
        var toggle=document.getElementById("themeToggle");
        if(toggle){
          toggle.setAttribute("aria-label", theme==="dark" ? "Váltás világos témára" : "Váltás sötét témára");
        }
