      function bind(){
        var toggle=document.getElementById("themeToggle");
        var setDarkBtn=document.getElementById("setDark");
        var setLightBtn=document.getElementById("setLight");
        var clearBtn=document.getElementById("clearTheme");
        if(toggle) toggle.addEventListener("click", function(){toggleTheme();});
        if(setDarkBtn) setDarkBtn.addEventListener("click", function(){setTheme("dark");});
        if(setLightBtn) setLightBtn.addEventListener("click", function(){setTheme("light");});
        if(clearBtn) clearBtn.addEventListener("click", function(){
          safeRemove();
          applyTheme("dark");
          dispatch("dark");
          syncUI();
        });
        window.addEventListener("storage", function(ev){
          if(!ev) return;
          if(ev.key!==KEY) return;
          var t=normalize(ev.newValue) || "dark";
          applyTheme(t);
          dispatch(t);
          syncUI();
        });
        window.addEventListener("themechange", function(){syncUI();});
      }

      function initSystemPanel(){
        var lang = navigator.language || "";
        var tz = "";
        try{
          tz = Intl.DateTimeFormat().resolvedOptions().timeZone || "";
        }catch(e){
          tz = "";
