        var tzValue=document.getElementById("tzValue");
        var screenValue=document.getElementById("screenValue");
        var langPill=document.getElementById("langPill");
        var tzPill=document.getElementById("tzPill");
        var screenPill=document.getElementById("screenPill");
        if(langValue) langValue.textContent = lang || "-";
        if(tzValue) tzValue.textContent = tz || "-";
        if(screenValue) screenValue.textContent = (sw && sh) ? (sw+"×"+sh+" @ "+dpr) : "-";
        if(langPill) langPill.textContent = lang ? "OK" : "N/A";
        if(tzPill) tzPill.textContent = tz ? "OK" : "N/A";
        if(screenPill) screenPill.textContent = (sw && sh) ? "OK" : "N/A";
      }

      function stamp(){
        var el=document.getElementById("buildStamp");
        if(!el) return;
        var d=new Date();
        var p=function(n){return String(n).padStart(2,"0");};
        el.textContent = d.getFullYear()+"-"+p(d.getMonth()+1)+"-"+p(d.getDate())+" "+p(d.getHours())+":"+p(d.getMinutes())+":"+p(d.getSeconds());
      }

      window.theme={
        getTheme: getTheme,
        setTheme: setTheme,
        toggleTheme: toggleTheme
      };

      bind();
      initSystemPanel();
      syncUI();
      stamp();
      setInterval(stamp,1000);
    })();
  </script>
